/** The app's own play-triangle glyph — ported from the design's own
 * play_arrow.svg, registered under AppIcon's "play_arrow" key in place of
 * Material's default PlayArrow, so every existing `AppIcon.of("play_arrow")`
 * call site picks it up automatically. Not a @Composable / per-color build
 * like the vectors below: every real usage renders it through Icon's own
 * `tint`, which recolors the whole glyph regardless of the fill baked in
 * here, so one shared instance is enough. */
val PlayArrowVector: ImageVector by lazy {
    ImageVector.Builder("play_arrow_custom", 18.dp, 21.dp, 18f, 21f).apply {
        addPath(
            pathData = addPathNodes("M17.25 9.22492C17.9167 9.60982 17.9167 10.5721 17.25 10.957L1.5 20.0502C0.833333 20.4351 0 19.954 0 19.1842V0.997675C0 0.227875 0.833333 -0.25325 1.5 0.131651L17.25 9.22492Z"),
            fill = SolidColor(Color.Black),
        )
    }.build()
}

