/** "Ajouter à Ma liste" glyph — ported from the design's own not_checked.svg:
 * a plus sign made of two rounded-cap bars (unlike Material's Add, which has
 * square-cut ends), so it visually matches [MyListCheckVector] below. */
@Composable
fun MyListAddVector(color: Color): ImageVector = remember(color) {
    ImageVector.Builder("mylist_add", 20.dp, 20.dp, 20f, 20f).apply {
        addPath(pathData = addPathNodes("M10 1V19"), fill = null, stroke = SolidColor(color), strokeLineWidth = 2f, strokeLineCap = StrokeCap.Round)
        addPath(pathData = addPathNodes("M1 10H19"), fill = null, stroke = SolidColor(color), strokeLineWidth = 2f, strokeLineCap = StrokeCap.Round)
    }.build()
}

/** "Déjà dans Ma liste" glyph — ported from the design's own checked.svg (two
 * rounded-cap bars forming a checkmark; the two `rect+matrix` pairs in that
 * SVG reduce to these two line segments once the transform is applied to
 * their centerlines — verified against the source coordinates). */
@Composable
fun MyListCheckVector(color: Color): ImageVector = remember(color) {
    ImageVector.Builder("mylist_check", 21.dp, 15.dp, 21f, 15f).apply {
        addPath(pathData = addPathNodes("M8.607 12.376L18.548 2.363"), fill = null, stroke = SolidColor(color), strokeLineWidth = 3.77f, strokeLineCap = StrokeCap.Round)
        addPath(pathData = addPathNodes("M8.471 12.302L2.705 6.899"), fill = null, stroke = SolidColor(color), strokeLineWidth = 3.77f, strokeLineCap = StrokeCap.Round)
    }.build()
}

